package org.eclipse.kura.core.keystore;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.KeyStore;
import java.security.cert.Certificate;
import java.security.cert.CertificateFactory;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.eclipse.kura.KuraException;
import org.eclipse.kura.crypto.CryptoService;
import org.junit.Rule;
import org.junit.rules.TemporaryFolder;
import org.osgi.service.component.ComponentContext;
import org.osgi.service.event.EventAdmin;

public abstract class AbstractFilesystemKeystoreServiceTest {

    protected static final String KEYSTORE_NAME = "key.store";
    protected static final String PASSWORD = "pass";
    private static final String CERT_FILE_PATH = "target/test-classes/cert";
    private static final String CORRUPTED_CONTENT = "corrupted";

    @Rule
    public TemporaryFolder folder = new TemporaryFolder();

    protected final CryptoService cryptoService = mock(CryptoService.class);
    protected FilesystemKeystoreServiceImpl keystoreService = new FilesystemKeystoreServiceImpl();
    protected final Map<String, Object> properties = new HashMap<>();
    protected Exception exception;

    protected void givenKeystoreWithCertificate(final String alias) throws Exception {
        writeKeystoreFile(KEYSTORE_NAME, alias);
    }

    protected void givenCorruptedFile(final String name) throws IOException {
        Files.write(keystoreFile(name).toPath(), CORRUPTED_CONTENT.getBytes(StandardCharsets.UTF_8));
    }

    protected void givenKeystoreMoveFails() {
        this.keystoreService = new FilesystemKeystoreServiceImpl(new AtomicFileWriter() {

            @Override
            void atomicMove(final Path source, final Path destination) throws IOException {
                if (destination.getFileName().toString().equals(KEYSTORE_NAME)) {
                    throw new IOException("simulated move failure");
                }
                super.atomicMove(source, destination);
            }
        });
    }

    protected void givenActivatedKeystoreService() throws Exception {
        activateKeystoreService();
    }

    protected void whenKeystoreServiceIsActivated() {
        try {
            activateKeystoreService();
        } catch (Exception e) {
            this.exception = e;
        }
    }

    protected void thenNoExceptionIsThrown() {
        assertNull(this.exception);
    }

    protected void thenKuraExceptionIsThrown() {
        assertTrue("expected KuraException but was " + this.exception, this.exception instanceof KuraException);
    }

    protected void thenKeystoreFileContainsOnly(final String name, final String password,
            final String... expectedAliases) throws Exception {
        final File file = keystoreFile(name);
        assertTrue(name + " should exist", file.isFile());

        final KeyStore keyStore = KeyStore.getInstance(KeyStore.getDefaultType());
        try (InputStream in = new FileInputStream(file)) {
            keyStore.load(in, password.toCharArray());
        }

        final List<String> actualAliases = Collections.list(keyStore.aliases());
        Collections.sort(actualAliases);
        final List<String> sortedExpectedAliases = new ArrayList<>(Arrays.asList(expectedAliases));
        Collections.sort(sortedExpectedAliases);
        assertEquals(sortedExpectedAliases, actualAliases);
    }

    protected void thenFileIsCorrupted(final String name) throws IOException {
        assertEquals(CORRUPTED_CONTENT,
                new String(Files.readAllBytes(keystoreFile(name).toPath()), StandardCharsets.UTF_8));
    }

    protected void thenDirectoryContainsOnly(final String... expectedNames) {
        final String[] actualNames = this.folder.getRoot().list();
        Arrays.sort(actualNames);
        Arrays.sort(expectedNames);
        assertEquals(Arrays.asList(expectedNames), Arrays.asList(actualNames));
    }

    protected void activateKeystoreService() throws Exception {
        when(this.cryptoService.decryptAes(any(char[].class))).thenAnswer(invocation -> invocation.getArgument(0));

        this.properties.put(FilesystemKeystoreServiceOptions.KEY_KEYSTORE_PATH, keystoreFile(KEYSTORE_NAME).getPath());
        this.properties.put(FilesystemKeystoreServiceOptions.KEY_KEYSTORE_PASSWORD, PASSWORD);

        this.keystoreService.setEventAdmin(mock(EventAdmin.class));
        this.keystoreService.setCryptoService(this.cryptoService);
        this.keystoreService.activate(mock(ComponentContext.class), this.properties);
    }

    protected void writeKeystoreFile(final String name, final String alias) throws Exception {
        final KeyStore keyStore = KeyStore.getInstance(KeyStore.getDefaultType());
        keyStore.load(null, null);
        keyStore.setCertificateEntry(alias, readCertificate());
        try (OutputStream out = new FileOutputStream(keystoreFile(name))) {
            keyStore.store(out, PASSWORD.toCharArray()); //NOSONAR
        }
    }

    protected File keystoreFile(final String name) {
        return new File(this.folder.getRoot(), name);
    }

    protected static Certificate readCertificate() throws Exception {
        try (InputStream in = new FileInputStream(CERT_FILE_PATH)) {
            return CertificateFactory.getInstance("X.509").generateCertificate(in);
        }
    }
}
